fun toggleEqLink() {
    _uiState.update { it.copy(eqLinked = !it.eqLinked) }
}

edits.newString:
fun toggleEqLink() {
    val linked = !_uiState.value.eqLinked
    _uiState.update { it.copy(eqLinked = linked) }
    engine?.setEqChannelLinked(linked)
}

