                ) { result ->
                    viewModel.onCaptureResult(result.resultCode, result.data)
                }
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    if (!state.isAppCaptureActive) {
                        Button(
                            onClick = {
